plany/ui/standards.css.before:
body[data-plany-surface="panel"] .field.module-name-field>input,
body[data-plany-surface="panel"] .field.module-name-field>.plany-text-confirmation>input{grid-column:2;grid-row:1;min-width:0;width:100%;margin:0}

.plany-production-issue{padding:12px 0;border-bottom:1px solid var(--line,#53645b)}
.plany-production-issue h4{font-size:14px;margin:6px 0}.plany-production-issue p,.plany-production-issue details{font-size:12px;overflow-wrap:break-word}
.central-partial-warning{padding:14px;margin:12px 0;border:2px solid #b34d26;border-radius:8px;font-size:13px;overflow-wrap:anywhere}

plany/ui/standards.css.after:
body[data-plany-surface="panel"] .field.module-name-field>input,
body[data-plany-surface="panel"] .field.module-name-field>.plany-text-confirmation>input{grid-column:2;grid-row:1;min-width:0;width:100%;margin:0}

/* Same approved, full-width piece-name field for loose and module-owned pieces.
   Override the generic two-column .field.module-name-field rule; keep the
   confirmation icon inside the text control and the dimension rows compact. */
body[data-plany-surface="panel"] #solo-piece .field.module-name-field,
body[data-plany-surface="panel"] #module-piece-editor .field.module-name-field{
  display:block;width:100%;min-width:0;margin-bottom:22px;
}
body[data-plany-surface="panel"] #solo-piece .field.module-name-field>.plany-text-confirmation,
body[data-plany-surface="panel"] #module-piece-editor .field.module-name-field>.plany-text-confirmation{
  display:block;width:100%;min-width:0;margin-top:6px;grid-column:auto;grid-row:auto;
}

.plany-production-issue{padding:12px 0;border-bottom:1px solid var(--line,#53645b)}
.plany-production-issue h4{font-size:14px;margin:6px 0}.plany-production-issue p,.plany-production-issue details{font-size:12px;overflow-wrap:break-word}
.central-partial-warning{padding:14px;margin:12px 0;border:2px solid #b34d26;border-radius:8px;font-size:13px;overflow-wrap:anywhere}

